<?php
require_once __DIR__.'/../includes/bootstrap.php';
$exists=!empty(admin_credentials()['username']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){verify_csrf();$u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');if(strlen($u)<3||strlen($p)<10){$error='اسم المستخدم 3 أحرف على الأقل وكلمة المرور 10 أحرف على الأقل.';}else{save_json('admin',['username'=>$u,'password_hash'=>password_hash($p,PASSWORD_DEFAULT),'created_at'=>date('c')]);audit('admin_setup',$u);header('Location: login.php?setup=1');exit;}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إعداد الإدارة | أبشر</title><link rel="stylesheet" href="../assets/admin-v7.css"></head><body class="auth-body"><form class="auth-card" method="post"><div class="auth-mark">A</div><span>ABSHAR CONTROL CENTER</span><h1>إعداد حساب الإدارة</h1><?php if($exists):?><p class="ok-box">تم إعداد حساب الإدارة بالفعل.</p><a class="admin-btn" href="login.php">الانتقال لتسجيل الدخول</a><?php else:?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($error):?><p class="error-box"><?=e($error)?></p><?php endif;?><label>اسم المستخدم<input name="username" required autocomplete="username"></label><label>كلمة المرور<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><button class="admin-btn" type="submit">إنشاء الحساب</button><?php endif;?></form></body></html>